  background-size: 5cqmin 5cqmin;
  -webkit-mask: radial-gradient(circle at 50% 45%,#000,transparent 72%);
  mask: radial-gradient(circle at 50% 45%,#000,transparent 72%);
}

.n4-mission .n4-copy {
  gap: 2cqmin;
}

.n4-mission .n4-head {
  display: flex;
  align-items: center;
  gap: 1.4cqmin;
}

.n4-mission .n4-radar {
  position: relative;
  width: clamp(18px,4cqmin,30px);
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb,var(--accent) 60%,transparent);
  background: conic-gradient(from 0deg,color-mix(in srgb,var(--accent) 70%,transparent),transparent 30%);
  animation: n4-mission-spin calc(2.4s / var(--k)) linear infinite;
}

.n4-mission .n4-num {
  margin: 0;
  font-size: clamp(76px,24cqmin,240px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: .02em;
  color: var(--accent);
  text-shadow: 0 0 .06em color-mix(in srgb,var(--accent) 80%,#fff),0 0 .3em color-mix(in srgb,var(--accent) 40%,transparent);
  animation: n4-mission-flicker calc(5s / var(--k)) steps(1) infinite;
}

.n4-mission .n4-title {
  font-size: clamp(16px,3.6cqmin,30px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: #eafff0;
}

.n4-mission .n4-log {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: .35em;
  font-size: clamp(11px,2cqmin,15px);
  color: color-mix(in srgb,var(--accent) 85%,#fff);
}

.n4-mission .n4-log li {
  overflow: hidden;
  white-space: nowrap;
  animation: n4-mission-type calc(1.1s / var(--k)) steps(34,end) both;
}

.n4-mission .n4-log li:nth-child(2) {
  animation-delay: calc(1.2s / var(--k));
}

.n4-mission .n4-log li:nth-child(3) {
  animation-delay: calc(2.4s / var(--k));
}

.n4-mission .n4-log li:last-child::after {
  content: "▌";
  margin-left: .2em;
  animation: n4-mission-blink 1s steps(1) infinite;
}

.n4-mission .n4-sub {
  color: #7c8c80;
}

.n4-mission .n4-cta {
  background: var(--accent);
  color: #00160a;
  font-family: inherit;
  letter-spacing: .04em;
}

@keyframes n4-mission-flicker {
  0%,100% {
    opacity: 1;
  }
  42% {
    opacity: .55;
  }
  43% {
    opacity: 1;
  }
  78% {
    opacity: .8;
  }
  79% {
    opacity: 1;
  }
}

@keyframes n4-mission-type {
  from {
    max-width: 0;
  }
  to {
    max-width: 48ch;
  }
}

@keyframes n4-mission-blink {
  50% {
    opacity: 0;
  }
}

