document.querySelectorAll(".n4-airport").forEach((el) => {
  const cells = el.querySelectorAll(".n4-flip b");
  const C = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789?-:";
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const timers = [];
  const flip = () => cells.forEach((b, i) => {
    const fin = b.dataset.c; let n = 5 + (i % 9) * 2;
    const tick = () => { b.classList.remove("f"); void b.offsetWidth; b.classList.add("f"); b.textContent = --n > 0 ? C[Math.floor(Math.random() * C.length)] : fin === " " ? "\u00a0" : fin; if (n > 0) timers.push(setTimeout(tick, 75)); };
    timers.push(setTimeout(tick, 300 + i * 35));
  });
  if (!rm) flip();
  const iv = rm ? 0 : setInterval(flip, 8000);
});

