// Parallax con el puntero: JavaScript del DOM, el mismo de la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  const drum = el.querySelector(".n4-drum");
  const knob = el.querySelector(".n4-knob");
  const progs = el.querySelectorAll(".n4-progs i");
  const live = el.querySelector(".n4-sr");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  const SPEED = [80, 200, 640];
  let p = 0, v = 0, a = 0, last = performance.now(), raf = 0;
  const tick = (now) => {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    v += (SPEED[p] * k - v) * Math.min(1, dt * 1.4);
    a = (a + v * dt) % 360;
    drum.style.transform = "rotate(" + a.toFixed(1) + "deg)";
    raf = requestAnimationFrame(tick);
  };
  knob.addEventListener("click", () => {
    p = (p + 1) % 3;
    knob.style.setProperty("--r", p * 40 - 40 + "deg");
    progs.forEach((x, i) => x.classList.toggle("n4-on", i === p));
    live.textContent = progs[p].textContent;
  });
  if (!rm) raf = requestAnimationFrame(tick);
  return () => cancelAnimationFrame(raf);
}

export default function NotFoundLaundry() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
