                <div className="n4-drum"><svg viewBox="0 0 100 100"><path d="M9 0l6 3h4l6-3 9 7-5 7-4-2v18H9V12l-4 2-5-7z" fill="#5b8def" transform="translate(10 48) rotate(-24) scale(.95)" /><path d="M9 0h11v15c0 3 1.5 5 5 7 4.5 2.5 5.5 7.5 1.5 10.5-3.5 2.5-8 1.5-12-1L5 26C1 23 .5 18 4 15l5-4z" fill="#ffd166" transform="translate(58 10) rotate(38) scale(.8)" /><path d="M9 0h11v15c0 3 1.5 5 5 7 4.5 2.5 5.5 7.5 1.5 10.5-3.5 2.5-8 1.5-12-1L5 26C1 23 .5 18 4 15l5-4z" fill="#2a9d8f" transform="translate(24 14) rotate(-52) scale(.75)" /><rect x="0" y="0" width="30" height="17" rx="3" fill="#f4a3c0" transform="translate(48 62) rotate(14)" /><path d="M0 4h30M0 9h30" stroke="#fff" strokeWidth="1.6" opacity=".55" transform="translate(48 62) rotate(14)" /><g transform="translate(62 30) rotate(112) scale(.95)"><path className="n4-sock" d="M9 0h11v15c0 3 1.5 5 5 7 4.5 2.5 5.5 7.5 1.5 10.5-3.5 2.5-8 1.5-12-1L5 26C1 23 .5 18 4 15l5-4z" /><text className="n4-st" x="13.5" y="22" transform="rotate(-90 13.5 19)">404</text></g></svg></div>
