document.querySelectorAll(".n4-elevator").forEach((el) => {
  const btns = el.querySelectorAll(".n4-fb");
  const lift = el.querySelector(".n4-lift");
  const msg = el.querySelector(".n4-msg");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  const pos = (f) => (f === 404 ? 7 : f);
  let cur = 0, timer = 0;
  const go = (b) => {
    const f = Number(b.dataset.f);
    const steps = Math.abs(pos(f) - pos(cur));
    clearTimeout(timer);
    btns.forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
    lift.classList.remove("n4-lost");
    msg.textContent = "";
    lift.style.setProperty("--d", 0.4 + steps * 0.25 + "s");
    lift.style.setProperty("--a", (f === 404 ? 86 : -60 + 24 * f) + "deg");
    cur = f;
    timer = setTimeout(() => {
      if (f !== 404) b.setAttribute("aria-pressed", "false");
      else {
        lift.classList.add("n4-lost");
        msg.textContent = "Esta planta no existe";
      }
    }, rm ? 0 : (400 + steps * 250) / k + 120);
  };
  btns.forEach((b) => b.addEventListener("click", () => go(b)));
  const auto = setTimeout(() => go(btns[btns.length - 1]), rm ? 0 : 900 / k);
});

