document.querySelectorAll(".n4-pharmacy").forEach((el) => {
  const grid = el.querySelector(".n4-dots");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  const N = 21;
  if (!grid.children.length) for (let i = 0; i < N * N; i++) grid.appendChild(document.createElement("i"));
  const cells = grid.children;
  const F = { "4": ["101", "101", "111", "001", "001"], "0": ["111", "101", "101", "101", "111"], ":": ["0", "1", "0", "1", "0"] };
  const cross = (x, y) => (x >= 7 && x < 14) || (y >= 7 && y < 14);
  const lit = (x, y) => cells[y * N + x].classList.add("n4-on");
  const clear = () => { for (let i = 0; i < cells.length; i++) cells[i].classList.remove("n4-on"); };
  const text = (s, x0, y0) => {
    let x = x0;
    for (const ch of s) {
      F[ch].forEach((row, y) => row.split("").forEach((b, dx) => { if (b === "1" && x + dx >= 0 && x + dx < N) lit(x + dx, y0 + y); }));
      x += F[ch][0].length + 1;
    }
  };
  const each = (fn) => { for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) if (cross(x, y) && fn(x, y)) lit(x, y); };
  let t = 0;
  const frame = () => {
    clear();
    const s = t % 100;
    if (s < 24) each((x, y) => Math.max(Math.abs(x - 10), Math.abs(y - 10)) === s % 12);
    else if (s < 58) text("404", 21 - (s - 24), 8);
    else if (s < 82) { if (s % 8 < 6) text("4:04", 4, 8); }
    else if (Math.floor(s / 5) % 2 === 0) each(() => true);
    t++;
  };
  let iv = 0;
  if (rm) text("404", 5, 8);
  else iv = setInterval(frame, 90 / k);
});

