// Parallax con el puntero: JavaScript del DOM, el mismo de la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  const now = el.querySelector(".n4-now");
  const note = el.querySelector(".n4-note");
  const tk = el.querySelector(".n4-tk");
  const pull = el.querySelector(".n4-pull");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  const SEQ = [401, 402, 403, 405, 406];
  let i = 0, tm = 0;
  const tick = () => {
    i = (i + 1) % SEQ.length;
    now.textContent = String(SEQ[i]);
    now.classList.remove("n4-ding");
    void now.offsetWidth;
    now.classList.add("n4-ding");
    note.textContent = SEQ[i] > 404 ? "¿Y el 404? Se lo han saltado." : "";
  };
  const iv = setInterval(tick, 1900 / k);
  pull.addEventListener("click", () => {
    clearTimeout(tm);
    tk.classList.remove("n4-new");
    tk.classList.add("n4-gone");
    tm = setTimeout(() => {
      tk.classList.remove("n4-gone");
      void tk.offsetWidth;
      tk.classList.add("n4-new");
    }, rm ? 0 : 380 / k);
  });
  return () => { clearInterval(iv); clearTimeout(tm); };
}

export default function NotFoundQueue() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div ref={ref}>
        <main className="n4-queue">
          <div className="n4-copy">
            <div className="n4-desk">
              <div className="n4-board">
                <span className="n4-lbl">Turno</span>
                <span className="n4-led" translate="no"><i aria-hidden="true">888</i><b className="n4-now">401</b></span>
              </div>
              <div className="n4-disp">
                <i className="n4-body" aria-hidden="true"><i>Turno</i></i>
                <div className="n4-roll"><div className="n4-tk"><small>Su turno</small><b translate="no">404</b><em>Por favor, espere</em></div></div>
                <button className="n4-pull" type="button">Coger número</button>
              </div>
            </div>
            <p className="n4-note" aria-live="polite"></p>
            <h1 className="n4-title">Su turno ha pasado de largo.</h1>
