// Parallax con el puntero: JavaScript del DOM, el mismo de la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  const cv = el.querySelector(".n4-cv");
  const ctx = cv.getContext("2d");
  const score = el.querySelector(".n4-score");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  const W = 260, H = 160, BW = 18, BH = 8;
  const GLYPH = { "4": ["101", "101", "111", "001", "001"], "0": ["111", "101", "101", "101", "111"] };
  const COLS = ["#ff5d5d", "#ff9f43", "#ffd43b", "#51cf66", "#4dabf7"];
  let bricks = [];
  const build = () => {
    bricks = [];
    let gx = 0;
    for (const ch of "404") {
      GLYPH[ch].forEach((row, y) => row.split("").forEach((b, x) => { if (b === "1") bricks.push({ x: 21 + (gx + x) * 20, y: 16 + y * 10, c: COLS[y], on: true }); }));
      gx += 4;
    }
  };
  let px = W / 2, target = W / 2, manual = 0, pts = 0, raf = 0, last = 0, started = !rm;
  const ball = { x: W / 2, y: H - 30, vx: 1.2, vy: -1.6 };
  const reset = () => { ball.x = px; ball.y = H - 24; ball.vx = (Math.random() < 0.5 ? -1 : 1) * 1.2; ball.vy = -1.6; };
  const step = (f) => {
    const now = performance.now();
    if (now > manual) target = ball.x + Math.sin(now / 700) * 10;
    px += (target - px) * (now > manual ? 0.14 : 0.4);
    px = Math.max(20, Math.min(W - 20, px));
    ball.x += ball.vx * f;
    ball.y += ball.vy * f;
    if (ball.x < 3 || ball.x > W - 3) { ball.vx *= -1; ball.x = Math.max(3, Math.min(W - 3, ball.x)); }
    if (ball.y < 3) ball.vy = Math.abs(ball.vy);
    if (ball.vy > 0 && ball.y > H - 15 && ball.y < H - 6 && Math.abs(ball.x - px) < 23) {
      ball.vy = -Math.abs(ball.vy);
      ball.vx = (ball.x - px) / 12;
      if (Math.abs(ball.vx) < 0.5) ball.vx = ball.vx < 0 ? -0.5 : 0.5;
    }
    if (ball.y > H + 6) reset();
    for (const b of bricks) {
      if (b.on && ball.x > b.x - 2 && ball.x < b.x + BW + 2 && ball.y > b.y - 2 && ball.y < b.y + BH + 2) {
        b.on = false;
        ball.vy *= -1;
        pts += 10;
        score.textContent = String(pts).padStart(3, "0");
        break;
      }
    }
    if (bricks.every((b) => !b.on)) build();
  };
  const draw = () => {
    ctx.fillStyle = "#060b08";
    ctx.fillRect(0, 0, W, H);
    for (const b of bricks) {
      if (!b.on) continue;
      ctx.fillStyle = b.c;
      ctx.fillRect(b.x, b.y, BW, BH);
      ctx.fillStyle = "rgba(255,255,255,.28)";
      ctx.fillRect(b.x, b.y, BW, 2);
    }
    ctx.fillStyle = "#e9f5ec";
    ctx.fillRect(Math.round(px - 20), H - 12, 40, 5);
    ctx.fillRect(Math.round(ball.x - 2), Math.round(ball.y - 2), 4, 4);
  };
  const loop = (t) => {
    const f = last ? Math.min(3, (t - last) / 16.67) * k : 1;
    last = t;
    step(f);
    draw();
    raf = requestAnimationFrame(loop);
  };
  const start = () => { if (!started) { started = true; raf = requestAnimationFrame(loop); } };
  cv.addEventListener("pointermove", (e) => {
    const r = cv.getBoundingClientRect();
    target = ((e.clientX - r.left) / r.width) * W;
    manual = performance.now() + 3000;
  });
  cv.addEventListener("pointerdown", start);
  cv.addEventListener("keydown", (e) => {
    if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
    e.preventDefault();
    target = px + (e.key === "ArrowLeft" ? -26 : 26);
    manual = performance.now() + 3000;
    start();
  });
  build();
  draw();
  if (started) raf = requestAnimationFrame(loop);
  return () => cancelAnimationFrame(raf);
}

export default function NotFoundArcade() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div ref={ref}>
        <main className="n4-arcade">
          <div className="n4-copy">
            <div className="n4-cab">
              <p className="n4-marq" aria-hidden="true">Rompe el 404</p>
              <div className="n4-hud" aria-hidden="true"><span>Puntos</span><b className="n4-score" translate="no">000</b><span>Vidas</span><b translate="no">∞</b></div>
              <div className="n4-screen"><canvas className="n4-cv" width="260" height="160" tabIndex={0} role="img" aria-label="Juego de ladrillos: mueve la pala con las flechas o con el puntero"></canvas></div>
            </div>
            <h1 className="n4-title">Fin de la partida para esta página.</h1>
