document.querySelectorAll(".n4-moles").forEach((el) => {
  const holes = Array.from(el.querySelectorAll(".n4-hole"));
  const out = el.querySelector(".n4-count b");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  let cur = -1, n = 0, t1 = 0, t2 = 0;
  const pop = () => {
    let i = Math.floor(Math.random() * holes.length);
    if (i === cur) i = (i + 1) % holes.length;
    cur = i;
    holes[i].classList.add("n4-up");
    t1 = setTimeout(() => {
      holes[i].classList.remove("n4-up");
      cur = -1;
      t2 = setTimeout(pop, (300 + Math.random() * 500) / k);
    }, (900 + Math.random() * 400) / k);
  };
  holes.forEach((h, i) => h.addEventListener("click", () => {
    if (i !== cur) return;
    clearTimeout(t1);
    clearTimeout(t2);
    n++;
    out.textContent = String(n);
    h.classList.remove("n4-up");
    h.classList.add("n4-hit");
    cur = -1;
    t2 = setTimeout(() => { h.classList.remove("n4-hit"); pop(); }, 420 / k);
  }));
  t2 = setTimeout(pop, 600 / k);
});

