// Parallax con el puntero: JavaScript del DOM, el mismo de la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  const box = el.querySelector(".n4-box");
  const board = el.querySelector(".n4-board");
  const tiles = Array.from(el.querySelectorAll(".n4-tile"));
  const st = el.querySelector(".n4-st");
  const mix = el.querySelector(".n4-mix");
  const START = st.textContent;
  const pos = tiles.map((_, i) => i);
  let empty = 8;
  const paint = () => tiles.forEach((t, i) => {
    t.style.setProperty("--x", String(pos[i] % 3));
    t.style.setProperty("--y", String(Math.floor(pos[i] / 3)));
  });
  const adj = (a, b) => Math.abs((a % 3) - (b % 3)) + Math.abs(Math.floor(a / 3) - Math.floor(b / 3)) === 1;
  const solved = () => pos.every((p, j) => p === j);
  const swap = (i) => { const c = pos[i]; pos[i] = empty; empty = c; };
  const move = (i) => {
    if (!adj(pos[i], empty)) return;
    swap(i);
    paint();
    const done = solved();
    box.classList.toggle("n4-done", done);
    st.textContent = done ? "Completo. La página sigue sin aparecer." : START;
  };
  const shuffle = () => {
    let prev = -1;
    do {
      for (let n = 0; n < 80; n++) {
        const opts = tiles.map((_, i) => i).filter((i) => i !== prev && adj(pos[i], empty));
        const i = opts[Math.floor(Math.random() * opts.length)];
        swap(i);
        prev = i;
      }
    } while (solved());
    paint();
    box.classList.remove("n4-done");
    st.textContent = START;
  };
  tiles.forEach((t, i) => t.addEventListener("click", () => move(i)));
  board.addEventListener("keydown", (e) => {
    const d = { ArrowLeft: 1, ArrowRight: -1, ArrowUp: 3, ArrowDown: -3 }[e.key];
    if (!d) return;
    e.preventDefault();
    const cell = empty + d;
    if (cell < 0 || cell > 8 || (Math.abs(d) === 1 && Math.floor(cell / 3) !== Math.floor(empty / 3))) return;
    const i = pos.indexOf(cell);
    move(i);
    tiles[i].focus();
  });
  mix.addEventListener("click", shuffle);
  shuffle();
}

