document.querySelectorAll(".n4-claw").forEach((el) => {
  const m = el.querySelector(".n4-machine");
  const toys = Array.from(el.querySelectorAll(".n4-front"));
  const cred = el.querySelector(".n4-cred b");
  const live = el.querySelector(".n4-sr");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  let x = 50, busy = false, credits = 3;
  const timers = [];
  const at = (ms, fn) => timers.push(setTimeout(fn, rm ? 0 : ms / k));
  const place = () => m.style.setProperty("--x", String(x));
  const shift = (d) => { if (!busy) { x = Math.max(8, Math.min(82, x + d * 6)); place(); } };
  const drop = () => {
    if (busy) return;
    busy = true;
    m.classList.add("n4-busy", "n4-down");
    if (credits === 0) credits = 3;
    credits--;
    cred.textContent = String(credits);
    live.textContent = "";
    const near = toys.find((p) => Math.abs(Number(p.style.getPropertyValue("--x")) - x) < 10);
    at(900, () => m.classList.add("n4-shut"));
    at(1250, () => { m.classList.remove("n4-down"); if (near) near.classList.add("n4-lift"); });
    at(1750, () => {
      if (near) { near.classList.remove("n4-lift"); near.classList.add("n4-fall"); }
      live.textContent = near ? "Casi. Se ha escapado." : "Aquí no hay nada.";
    });
    at(2400, () => {
      m.classList.remove("n4-shut", "n4-busy");
      toys.forEach((p) => p.classList.remove("n4-fall"));
      busy = false;
    });
  };
  el.querySelectorAll(".n4-mv").forEach((b) => b.addEventListener("click", () => shift(Number(b.dataset.d))));
  el.querySelector(".n4-drop").addEventListener("click", drop);
  m.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") { e.preventDefault(); shift(e.key === "ArrowLeft" ? -1 : 1); }
    else if (e.key === "ArrowDown") { e.preventDefault(); drop(); }
  });
  place();
});

