                <i className="n4-toy n4-back" style={{ "--x": "22", "--c": "#7bd389" } as CSSProperties}></i><i className="n4-toy n4-back" style={{ "--x": "45", "--c": "#ffa94d" } as CSSProperties}></i><i className="n4-toy n4-back" style={{ "--x": "66", "--c": "#b197fc" } as CSSProperties}></i>
