document.querySelectorAll(".n4-lighthouse").forEach((el) => {
  const sky = el.querySelector(".n4-sky");
  const lamp = el.querySelector(".n4-lamp");
  const lit = el.querySelector(".n4-lit");
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  let px = 0, py = 0, until = 0, raf = 0, sx = -1, sy = 0;
  const t0 = performance.now();
  const frame = (t) => {
    const r = el.getBoundingClientRect(), l = lamp.getBoundingClientRect(), b = lit.getBoundingClientRect();
    const s = r.width / el.offsetWidth || 1;
    const lx = (l.left + l.width / 2 - r.left) / s, ly = (l.top + l.height / 2 - r.top) / s;
    const bx = (b.left - r.left) / s, by = (b.top - r.top) / s, bw = b.width / s, bh = b.height / s;
    let tx = px, ty = py;
    if (t > until) { tx = bx + bw * (0.5 + 0.6 * Math.sin(((t - t0) / 1000) * 0.7 * k)); ty = by + bh * 0.55; }
    if (sx < 0 || rm) { sx = tx; sy = ty; }
    sx += (tx - sx) * 0.08;
    sy += (ty - sy) * 0.08;
    sky.style.setProperty("--lx", lx.toFixed(1) + "px");
    sky.style.setProperty("--ly", ly.toFixed(1) + "px");
    sky.style.setProperty("--a", ((Math.atan2(sy - ly, sx - lx) * 180) / Math.PI).toFixed(2) + "deg");
    lit.style.setProperty("--mx", (sx - bx).toFixed(1) + "px");
    lit.style.setProperty("--my", (sy - by).toFixed(1) + "px");
    if (!rm) raf = requestAnimationFrame(frame);
  };
  const move = (e) => {
    const r = el.getBoundingClientRect();
    const s = r.width / el.offsetWidth || 1;
    px = (e.clientX - r.left) / s;
    py = (e.clientY - r.top) / s;
    until = performance.now() + 2500;
    if (rm) frame(performance.now());
  };
  el.addEventListener("pointermove", move);
  raf = requestAnimationFrame(frame);
});

