    const r = rec.getBoundingClientRect();
    return (Math.atan2(e.clientY - r.top - r.height / 2, e.clientX - r.left - r.width / 2) * 180) / Math.PI;
  };
  const loop = (t) => {
    const dt = Math.min(0.05, (t - last) / 1000);
    last = t;
    if (drag === null) {
      v += ((on ? 200 * k : 0) - v) * Math.min(1, dt * (on ? 1.6 : 1.1));
      a += v * dt;
    }
    rec.style.transform = "rotate(" + a.toFixed(1) + "deg)";
    raf = requestAnimationFrame(loop);
  };
  const toggle = () => {
    on = !on;
    btn.setAttribute("aria-pressed", String(on));
    tt.classList.toggle("n4-on", on);
    now.textContent = on ? "Pista no encontrada" : "";
  };
  btn.addEventListener("click", toggle);
  rec.addEventListener("pointerdown", (e) => { drag = ang(e); rec.setPointerCapture(e.pointerId); });
  rec.addEventListener("pointermove", (e) => {
    if (drag === null) return;
    const n = ang(e);
    let d = n - drag;
    if (d > 180) d -= 360;
    if (d < -180) d += 360;
    a += d;
    drag = n;
  });
  const up = () => { drag = null; };
  rec.addEventListener("pointerup", up);
  rec.addEventListener("pointercancel", up);
  raf = requestAnimationFrame(loop);
  const auto = rm ? 0 : setTimeout(toggle, 700 / k);
  return () => { cancelAnimationFrame(raf); clearTimeout(auto); };
}

export default function NotFoundVinyl() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div ref={ref}>
        <main className="n4-vinyl">
          <div className="n4-copy">
            <div className="n4-tt">
              <div className="n4-plat" aria-hidden="true"><div className="n4-rec"><span className="n4-lab"><b translate="no">404</b><small>Cara B</small></span></div><i className="n4-shine"></i></div>
              <div className="n4-arm" aria-hidden="true"><i className="n4-tube"></i><i className="n4-pivot"></i></div>
              <span className="n4-rpm" aria-hidden="true" translate="no">33</span>
              <button className="n4-play" type="button" aria-pressed="false">Reproducir</button>
              <p className="n4-now" aria-live="polite"></p>
            </div>
            <span className="n4-tag">Cara B, pista 404</span>
            <h1 className="n4-title">Esta pista no está en el disco.</h1>
            <p className="n4-sub">Le hemos dado la vuelta al vinilo y la página tampoco está en la cara B. Prueba con otro álbum o vuelve al inicio.</p>
            <a className="n4-cta" href="/">Volver al inicio</a>
          </div>
        </main>
      </div>
    </>
  );
}

