// Parallax con el puntero: JavaScript del DOM, el mismo de la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  const dash = el.querySelector(".n4-dash");
  el.querySelector(".n4-start").addEventListener("click", () => {
    dash.classList.remove("n4-go");
    void dash.offsetWidth;
    dash.classList.add("n4-go");
  });
}

export default function NotFoundGarage() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div ref={ref}>
        <main className="n4-garage">
