css:
.n4-aquarium {
  --accent: #ffb703;
  --k: 1;
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  container-type: size;
  display: grid;
  place-items: center;
  background: #000;
  color: #f5f5f7;
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Display","Inter","Segoe UI",system-ui,sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: center;
  line-height: 1.4;
}

.n4-aquarium *,.n4-aquarium *::before,.n4-aquarium *::after {
  box-sizing: border-box;
}

.n4-aquarium .n4-copy {
  position: relative;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.6cqmin;
  width: 100%;
  max-width: 680px;
  padding: 0 6cqw;
}

.n4-aquarium .n4-title {
  margin: 0;
  font-size: clamp(17px,4.2cqmin,36px);
  font-weight: 600;
  letter-spacing: -.02em;
  line-height: 1.15;
  text-wrap: balance;
}

.n4-aquarium .n4-sub {
  margin: 0;
  max-width: 34em;
  font-size: clamp(13px,2.4cqmin,18px);
  color: #a1a1a6;
  text-wrap: balance;
}

.n4-aquarium .n4-tag {
  font: 600 clamp(10px,1.9cqmin,13px)/1 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--accent);
}

.n4-aquarium .n4-cta {
  margin-top: 1.8cqmin;
  display: inline-flex;
  align-items: center;
  gap: .5em;
  padding: .85em 1.5em;
  border-radius: 999px;
  background: #f5f5f7;
  color: #000;
  font-size: clamp(13px,2.2cqmin,16px);
  font-weight: 600;
  text-decoration: none;
  transition: transform .3s cubic-bezier(.25,.1,.25,1),box-shadow .3s cubic-bezier(.25,.1,.25,1);
}

.n4-aquarium .n4-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px -10px var(--accent);
}

.n4-aquarium .n4-cta:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.n4-aquarium .n4-stars,.n4-aquarium .n4-stars2 {
  position: absolute;
  inset: -4%;
  pointer-events: none;
}

.n4-aquarium .n4-stars {
  background-image: radial-gradient(1px 1px at 8% 12%,#fff 60%,transparent),radial-gradient(1px 1px at 22% 68%,#fff 60%,transparent),radial-gradient(1.5px 1.5px at 35% 24%,#fff 60%,transparent),radial-gradient(1px 1px at 48% 82%,#fff 60%,transparent),radial-gradient(1px 1px at 57% 9%,#fff 60%,transparent),radial-gradient(1.5px 1.5px at 66% 44%,#fff 60%,transparent),radial-gradient(1px 1px at 74% 72%,#fff 60%,transparent),radial-gradient(1px 1px at 86% 18%,#fff 60%,transparent),radial-gradient(1.5px 1.5px at 93% 58%,#fff 60%,transparent),radial-gradient(1px 1px at 14% 42%,#fff 60%,transparent),radial-gradient(1px 1px at 40% 55%,#fff 60%,transparent),radial-gradient(1px 1px at 81% 90%,#fff 60%,transparent),radial-gradient(1px 1px at 4% 88%,#fff 60%,transparent),radial-gradient(1px 1px at 62% 30%,#fff 60%,transparent);
  opacity: .75;
  animation: n4-aquarium-tw calc(5s / var(--k)) ease-in-out infinite alternate;
}

.n4-aquarium .n4-stars2 {
  background-image: radial-gradient(2px 2px at 18% 30%,rgba(255,255,255,.9) 50%,transparent),radial-gradient(1.5px 1.5px at 72% 20%,rgba(255,255,255,.8) 50%,transparent),radial-gradient(2px 2px at 30% 85%,rgba(255,255,255,.7) 50%,transparent),radial-gradient(1.5px 1.5px at 88% 70%,rgba(255,255,255,.8) 50%,transparent),radial-gradient(2px 2px at 52% 60%,rgba(255,255,255,.6) 50%,transparent),radial-gradient(1.5px 1.5px at 6% 55%,rgba(255,255,255,.8) 50%,transparent);
  opacity: .55;
  animation: n4-aquarium-tw calc(7s / var(--k)) ease-in-out infinite alternate-reverse;
}

.n4-aquarium [data-depth] {
  transition: transform .9s cubic-bezier(.2,.7,.2,1);
}

@keyframes n4-aquarium-tw {
  from {
    opacity: .3;
  }
}

@keyframes n4-aquarium-spin {
  to {
    transform: rotate(1turn);
  }
}

@keyframes n4-aquarium-fade {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
}

@media (prefers-reduced-motion:reduce) {
  .n4-aquarium *,.n4-aquarium *::before,.n4-aquarium *::after {
    animation: none!important;
    transition: none!important;
  }
}

.n4-aquarium {
  background: radial-gradient(80% 60% at 50% 28%,#0f4150,#03141a 75%);
  color: #e6f8fb;
}

.n4-aquarium .n4-tank {
  position: relative;
  overflow: hidden;
  width: min(68cqmin,470px);
  aspect-ratio: 16/9;
  font-size: min(2cqmin,14px);
  margin-bottom: 1.8cqmin;
  border-radius: 1em;
  background: linear-gradient(rgba(255,255,255,.22) 0 .8em,transparent .8em),linear-gradient(#45c4d8,#15829a 50%,#0a4f66);
  box-shadow: inset 0 0 0 .35em rgba(220,245,250,.35),0 0 0 .5em #0b2b36,0 2em 3em -1.5em rgba(0,0,0,.7);
  touch-action: none;
}

.n4-aquarium .n4-caus {
  position: absolute;
  inset: 0;
  background: repeating-radial-gradient(ellipse at 30% 20%,rgba(255,255,255,.09) 0 1em,transparent 1em 2.6em),repeating-radial-gradient(ellipse at 70% 10%,rgba(255,255,255,.07) 0 .8em,transparent .8em 2.2em);
  animation: n4-aquarium-caus calc(9s / var(--k)) ease-in-out infinite alternate;
}

.n4-aquarium .n4-weed {
  position: absolute;
  left: 0;
  bottom: 8%;
  width: 100%;
  height: 56%;
}

.n4-aquarium .n4-weed path {
  fill: none;
  stroke: #2f9e62;
  stroke-width: 5;
  stroke-linecap: round;
  transform-box: fill-box;
  transform-origin: 50% 100%;
  animation: n4-aquarium-sway calc(var(--d) / var(--k)) ease-in-out infinite alternate;
}

.n4-aquarium .n4-weed path:nth-child(2n) {
  stroke: #5cc27f;
  stroke-width: 4;
}

.n4-aquarium .n4-sand {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 14%;
  border-radius: 50% 50% 0 0/1.4em 1.4em 0 0;
  background: radial-gradient(circle,rgba(120,90,50,.35) 0 1px,transparent 1.5px) 0 0/.6em .6em,linear-gradient(#ead6a4,#cdb57d);
}

.n4-aquarium .n4-fish {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: calc(var(--s) * 4.6em);
  height: auto;
  translate: -50% -50%;
  scale: var(--f,1) 1;
  fill: var(--c);
  filter: drop-shadow(0 .3em .3em rgba(0,0,0,.2));
}

.n4-aquarium .n4-fish circle {
  fill: #111;
}

.n4-aquarium .n4-stripe {
  fill: none;
  stroke: rgba(255,255,255,.75);
  stroke-width: 2.5;
}

.n4-aquarium .n4-tail {
  transform-box: fill-box;
  transform-origin: 0 50%;
  animation: n4-aquarium-tail calc(.35s / var(--k)) ease-in-out infinite alternate;
}

.n4-aquarium .n4-bub {
  position: absolute;
  bottom: 12%;
  left: var(--x);
  width: var(--s);
  height: var(--s);
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.7);
  background: radial-gradient(circle at 35% 30%,rgba(255,255,255,.85) 0 18%,transparent 24%);
  opacity: 0;
  animation: n4-aquarium-bub calc(var(--d) / var(--k)) linear var(--dl) infinite;
}

.n4-aquarium .n4-plate {
  position: absolute;
  z-index: 3;
  right: .9em;
  bottom: .7em;
  display: grid;
  gap: .15em;
  padding: .45em .75em;
  border-radius: .25em;
  text-align: left;
  background: linear-gradient(135deg,#f6dc8a,#b8862b 45%,#f1cf73 70%,#8a5e14);
  color: #2a1d05;
  box-shadow: 0 .2em .4em rgba(0,0,0,.4);
}

.n4-aquarium .n4-plate b {
  font: italic 600 1em/1 "Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,serif;
}

.n4-aquarium .n4-plate small {
  font: 700 .66em/1.1 "Helvetica Neue",Helvetica,Arial,system-ui,sans-serif;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.n4-aquarium .n4-title {
  font-size: clamp(20px,5cqmin,42px);
  font-weight: 700;
  letter-spacing: -.025em;
}

.n4-aquarium .n4-sub {
  color: #9fc4cd;
}

.n4-aquarium .n4-cta {
  background: var(--accent);
  color: #1d1400;
}

@keyframes n4-aquarium-caus {
  to {
    background-position: 3em 1em,-2em 2em;
  }
}

@keyframes n4-aquarium-sway {
  from {
    rotate: -6deg;
  }
  to {
    rotate: 6deg;
  }
}

@keyframes n4-aquarium-tail {
  to {
    scale: 1 .7;
  }
}

@keyframes n4-aquarium-bub {
  0% {
    transform: translate(0,0);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  50% {
    transform: translate(.6em,-7em);
  }
  90% {
    opacity: .9;
  }
  100% {
    transform: translate(-.3em,-14em);
    opacity: 0;
  }
}

