document.querySelectorAll(".n4-aquarium").forEach((el) => {
  const tank = el.querySelector(".n4-tank");
  const fish = Array.from(el.querySelectorAll(".n4-fish"));
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const k = parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  const st = fish.map((f, i) => ({ x: 0.18 + i * 0.16, y: 0.24 + ((i * 37) % 46) / 100, vx: (i % 2 ? -1 : 1) * 0.0015, vy: 0, f: i % 2 ? 1 : -1 }));
  let mx = -1, my = -1, raf = 0, last = performance.now();
  const put = () => st.forEach((s, i) => {
    fish[i].style.setProperty("--x", (s.x * 100).toFixed(2) + "%");
    fish[i].style.setProperty("--y", (s.y * 100).toFixed(2) + "%");
    fish[i].style.setProperty("--f", String(s.f));
  });
  const loop = (t) => {
    const dt = Math.min(3, (t - last) / 16.67) * k;
