  transition: transform .3s,opacity .3s;
}

.n4-mail .n4-env[aria-expanded="true"] .n4-seal {
  transform: scale(.3) rotate(40deg);
  opacity: 0;
}

.n4-mail .n4-stamp {
  position: absolute;
  z-index: 4;
  left: 5%;
  bottom: 24%;
  padding: .4em .7em;
  border: .24em double #c1121f;
