  animation: n4-mail-thump calc(.5s / var(--k)) cubic-bezier(.3,1.6,.5,1) .5s both;
}

.n4-mail .n4-lbl {
  position: absolute;
  z-index: 4;
  right: 6%;
  bottom: 9%;
  padding: .45em .6em;
