}

@keyframes n4-mail-nudge {
  0%,88%,100% {
    rotate: 0deg;
  }
  91% {
    rotate: -2deg;
  }
  94% {
    rotate: 2deg;
  }
  97% {
    rotate: -1deg;
  }
}

@keyframes n4-mail-thump {
  from {
    transform: scale(2.4);
    opacity: 0;
  }
}
