// Parallax con el puntero: JavaScript del DOM, el mismo de la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  const env = el.querySelector(".n4-env");
  env.addEventListener("click", () => env.setAttribute("aria-expanded", String(env.getAttribute("aria-expanded") !== "true")));
}

export default function NotFoundMail() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div ref={ref}>
        <main className="n4-mail">
          <div className="n4-copy">
            <button className="n4-env" type="button" aria-expanded="false" aria-label="Abrir el sobre">
              <span className="n4-back" aria-hidden="true"></span>
              <span className="n4-letter" aria-hidden="true"><b>Querida persona:</b><span>Hemos recorrido toda la calle y aquí no vive ninguna página 404.</span><em>El cartero</em></span>
              <span className="n4-front" aria-hidden="true"></span>
              <span className="n4-flap" aria-hidden="true"></span>
              <span className="n4-seal" aria-hidden="true" translate="no">404</span>
              <span className="n4-stamp" aria-hidden="true">Devuelto al remitente</span>
